const notifyAdvisoryLock = `-- name: NotifyAdvisoryLock :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

// NotifyAdvisoryLock serializes fan-outs per key (user flood counters,
// started-event collapse) until the transaction ends.
func (q *Queries) NotifyAdvisoryLock(ctx context.Context, lockKey string) error {
	_, err := q.db.Exec(ctx, notifyAdvisoryLock, lockKey)
	return err
}

